head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.createWindow = function(title, winId) {
    var src = "/sample/common_link/windowContainer_addText_WPF-994_(WSQ-246)_openTest.xml&txt=" + title;
    var windowCreated = windowContainer1.getWindowByWindowId(winId);
    windowContainer1.createWindow(title, null, src, title + " PAGE", winId);
    if (!windowCreated) {
        var selectedIdx = windowContainer1.getSelectedIndex();
        var statusDoc = scwin.__getDom($p.id + "windowContainer1_subWindow" + selectedIdx + "_status");
        if (statusDoc.children.length > 1) {
            return;
        }
        var tmpDoc = document.createElement("div");
        tmpDoc.setAttribute("id", "windowContainer1_subWindow" + selectedIdx + "_msg2");
        tmpDoc.setAttribute("style", "height:14px;float:right;padding-right:3px;");
        var textnode = document.createTextNode("any text..[tab : " + selectedIdx + "]");
        tmpDoc.appendChild(textnode);
        statusDoc.appendChild(tmpDoc);
    }
}
